INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_profile_devices_20261113', 'fact', 'Lenovo LOQ 15ARP9 hardware', 'Main laptop: Lenovo LOQ 15ARP9 (Type 83JC), AMD Ryzen 5 7235HS, 12 GB RAM, NVIDIA RTX 3050 Laptop 4 GB VRAM, ~477 GB SSD, Windows 11. Local inference must fit 4 GB VRAM; prefer lightweight local models and free cloud tiers.', 'merge_report_2026_11_13', '{"report_section":"profile","source_labels":["R1","D2"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["Jatin-Profile","Preferences","Profile-MOC"],"note":"01-Profile/Devices.md"}', 'high', 'personal', 'profile,hardware', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
