INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_profile_budget_20261113', 'fact', 'Student budget: free tiers only', 'Student budget is strictly low. No credit card; pays by UPI. Prefer free tiers that genuinely work, disclose cost and quota before recommending anything paid, and never make a paid service mandatory without explicit approval.', 'merge_report_2026_11_13', '{"report_section":"profile","source_labels":["R1","D2"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["Jatin-Profile","Preferences","Profile-MOC"],"note":"01-Profile/Budget.md"}', 'high', 'personal', 'profile,budget', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
