INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_daemon_identity_20261113', 'fact', 'DAEMON is Jatin''s assistant and second brain', 'DAEMON (Daemon_M1_bot) is Jatin''s personal assistant, second brain and chief of staff: tasks, reminders, project history, briefings, research, planning and natural conversation. It is inspired by an earlier DAEMON concept whose features are not proven in the current bot.', 'merge_report_2026_11_13', '{"report_section":"daemon","source_labels":["R1","P2"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["DAEMON-Stack","DAEMON-Behaviour-Rules","Projects-MOC"],"note":"06-Projects/DAEMON/DAEMON.md"}', 'high', 'personal', 'daemon', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
