INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_daemon_stack_20261113', 'fact', 'DAEMON stack: Worker + D1 + Telegram', 'DAEMON runs as a Cloudflare Worker with D1 as operational state and the Telegram bot Daemon_M1_bot as its interface. D1 is authoritative for tasks, reminders, scheduling, proposals and runtime memory. Repository: C:\dev\personal-ai-os, branch main.', 'merge_report_2026_11_13', '{"report_section":"daemon","source_labels":["R1","F1"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["DAEMON","Rule-Task-Approval","Projects-MOC"],"note":"06-Projects/DAEMON/Stack.md"}', 'high', 'personal', 'daemon,stack', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
