INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_daemon_behavior_20261113', 'fact', 'DAEMON behaviour rules', 'DAEMON must handle small talk naturally (no "no record of that" replies), must ask before creating any task or commitment, must never claim an action it did not commit, and must not repeat stored memory sentences verbatim.', 'merge_report_2026_11_13', '{"report_section":"daemon","source_labels":["R1","P2","F1"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["DAEMON","Rule-Task-Approval","Projects-MOC"],"note":"06-Projects/DAEMON/Behaviour-Rules.md"}', 'high', 'personal', 'daemon,behaviour', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
