INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_history_memory_model_20261113', 'fact', 'Predecessor memory model: Hot/Warm/Cold, Saptashva, Aruna, Cloak', 'Predecessor DAEMON designs proposed Hot/Warm/Cold memory tiers, a Saptashva Council of seven perspectives, Aruna synthesis and a Cloak privacy system. These are historical designs; none is verified as implemented in the current Cloudflare Worker bot.', 'merge_report_2026_11_13', '{"report_section":"history","source_labels":["R1","P3","P4"],"status":"historical","as_of":"2026-11-13","confidence":"medium","related":["DAEMON","Predecessor-History-MOC"],"note":"06-Projects/DAEMON/History/Memory-Model.md"}', 'medium', 'personal', 'daemon-history', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
