INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_history_general_agent_20261113', 'fact', 'Predecessor: General Agent, Daily Briefing, always-on hub', 'Earlier designs included a General Agent, a Daily Briefing and an always-on home hub on an older Android phone. The hub deployment was never confirmed. Treat these as predecessor concepts, not current capabilities.', 'merge_report_2026_11_13', '{"report_section":"history","source_labels":["R1","P3","P4"],"status":"historical","as_of":"2026-11-13","confidence":"medium","related":["DAEMON","Predecessor-History-MOC"],"note":"06-Projects/DAEMON/History/General-Agent-and-Briefing.md"}', 'medium', 'personal', 'daemon-history', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
