INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_career_directions_20261113', 'fact', 'Three co-important career directions', 'Three directions are equally important and none may be permanently deprioritised: (1) GSoC 2027 open-source contribution, (2) a first meaningful internship, (3) substantial original projects and learning. Rank work dynamically by deadlines and opportunity cost, and make trade-offs visible.', 'merge_report_2026_11_13', '{"report_section":"career","source_labels":["R1","P1"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["GSoC-2027","Internship","Portfolio","Career-MOC"],"note":"05-Career/Three-Directions.md"}', 'high', 'personal', 'career,goals', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
