INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_career_learning_20261113', 'fact', 'Learning roadmap', 'Learning loop: Course -> Skill -> Practice -> Evidence, with priority tiers MUST/SHOULD/JUST-IN-TIME/OPTIONAL. Foundations: Kaggle Python, SQL, Pandas, Intro/Intermediate ML; freeCodeCamp Python OOP; practical Git. Then Hugging Face LLM course, Qdrant vector search, LangGraph after orchestration basics, Made With ML for MLOps.', 'merge_report_2026_11_13', '{"report_section":"career","source_labels":["R1","D1","D2"],"status":"current","as_of":"2026-11-13","confidence":"medium","related":["DSA-and-Portfolio","AI-Engineering-Track","Learning-MOC"],"note":"04-Learning/Learning-Roadmap.md"}', 'medium', 'personal', 'learning,career', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
