INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_career_dsa_portfolio_20261113', 'fact', 'DSA and portfolio strategy', 'DSA: consistent practice, a 66-problem checklist with gaps in graphs, greedy, sliding window and binary-search-on-answer; VisuAlgo for concepts. Portfolio: a public patterns journal, one small genuinely useful tool, real bug fixes in open source, and build-in-public posts. Plans, not verified progress.', 'merge_report_2026_11_13', '{"report_section":"career","source_labels":["R1","P1"],"status":"current","as_of":"2026-11-13","confidence":"medium","related":["Learning-Roadmap","Portfolio","Learning-MOC"],"note":"04-Learning/DSA-and-Portfolio.md"}', 'medium', 'personal', 'learning,dsa,career', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
