INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_rule_task_approval_20261113', 'fact', 'Task creation always needs explicit approval', 'DAEMON must obtain Jatin''s explicit confirmation before creating or saving any task or commitment, whatever the source (message, email, calendar). Memory capture and task creation are separate policies. Confidential / consequential items are never auto-saved.', 'merge_report_2026_11_13', '{"report_section":"rules","source_labels":["R1","P2","P3","F1"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["Rule-Memory-Governance","Start-Here"],"note":"00-System/Rule-Task-Approval.md"}', 'high', 'personal', 'rules,tasks', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
