INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_rule_quiet_hours_20261113', 'fact', 'Quiet hours are adaptive', 'Quiet hours and summary timing must adapt to Jatin''s real schedule and wake time. No fixed 22:00-08:00, 23:00-08:00 or 08:30 rule should be imposed. Sleep is roughly 11 PM-12 AM; exam periods take precedence over routine activity.', 'merge_report_2026_11_13', '{"report_section":"rules","source_labels":["R1"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["Schedule","Start-Here"],"note":"00-System/Rule-Quiet-Hours.md"}', 'high', 'personal', 'rules,schedule', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
