INSERT OR IGNORE INTO memory_objects (id, type, title, canonical_text, source, metadata_json, trust, sensitivity, tags, created_at, updated_at) VALUES ('mem_ctx_rule_memory_governance_20261113', 'fact', 'Hybrid memory governance', 'Routine, stable, non-sensitive facts may be retained automatically. Sensitive, ambiguous, consequential or uncertain facts require Jatin''s approval. Forget requests need confirmation and verified propagation across connected stores. Corrections update the active fact and keep dated history. Never claim a store was updated without retrieval proof.', 'merge_report_2026_11_13', '{"report_section":"rules","source_labels":["R1","P2"],"status":"current","as_of":"2026-11-13","confidence":"high","related":["Rule-Task-Approval","Start-Here"],"note":"00-System/Rule-Memory-Governance.md"}', 'high', 'personal', 'rules,memory', '2026-11-13T00:00:00.000Z', '2026-11-13T00:00:00.000Z');
